function renderRules(focusSelector=null){let total=ruleGroups.reduce((n,g)=>n+g.rules.length,0);$('#ruleCount').textContent=`${total} ${total===1?'rule':'rules'}`;$('#rulesList').innerHTML=ruleGroups.map(group=>`<section class="rule-note-group ${collapsedRuleGroups.has(group.id)?'collapsed':''}"><header><div class="rule-label-title"><button data-toggle-rule-group="${group.id}" title="Open or close label"><b>⌃</b></button><div><span>LABEL</span><h4 contenteditable="true" spellcheck="true" data-rule-label="${group.id}" data-placeholder="Type label…">${escapeHtml(group.name)}</h4></div></div><div class="rule-label-actions"><button data-add-rule-group="${group.id}" title="Add rule">＋</button></div></header><div class="rule-cards">${group.rules.map((rule,i)=>`<div class="rule-note-row"><span class="rule-number">${i+1}.</span><p contenteditable="true" spellcheck="true" data-rule-text="${rule.id}" data-group="${group.id}" data-placeholder="Type your rule…">${escapeHtml(rule.text)}</p></div>`).join('')}</div></section>`).join('');$$('[data-toggle-rule-group]').forEach(b=>b.onclick=()=>{let id=b.dataset.toggleRuleGroup;collapsedRuleGroups.has(id)?collapsedRuleGroups.delete(id):collapsedRuleGroups.add(id);renderRules()});$$('[data-add-rule-group]').forEach(b=>b.onclick=()=>addBlankRule(b.dataset.addRuleGroup));$$('[data-rule-label]').forEach(el=>{el.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();el.blur()}};el.onblur=()=>commitRuleLabel(el)});$$('[data-rule-text]').forEach(el=>el.onblur=()=>commitRuleText(el));if(focusSelector)setTimeout(()=>{let el=$(focusSelector);el?.focus();if(el){let range=document.createRange(),sel=window.getSelection();range.selectNodeContents(el);range.collapse(false);sel.removeAllRanges();sel.addRange(range)}},30)}
function beginInlineLabel(){let group={id:'group-'+Date.now().toString(36),name:'',rules:[]};ruleGroups.push(group);collapsedRuleGroups.delete(group.id);renderRules(`[data-rule-label="${group.id}"]`)}
function addBlankRule(groupId){let group=ruleGroups.find(g=>g.id===groupId);if(!group)return;let rule={id:'rule-'+Date.now().toString(36),text:''};group.rules.push(rule);collapsedRuleGroups.delete(groupId);renderRules(`[data-rule-text="${rule.id}"]`)}
function commitRuleLabel(el){let group=ruleGroups.find(g=>g.id===el.dataset.ruleLabel),name=el.textContent.trim();if(!group)return;if(!name){ruleGroups=ruleGroups.filter(g=>g.id!==group.id);toast('Empty label removed.')}else group.name=name;saveRuleGroups();renderRules()}
function commitRuleText(el){let group=ruleGroups.find(g=>g.id===el.dataset.group),rule=group?.rules.find(r=>r.id===el.dataset.ruleText),text=el.textContent.trim();if(!group||!rule)return;if(!text){group.rules=group.rules.filter(r=>r.id!==rule.id);toast('Empty rule removed.')}else rule.text=text;saveRuleGroups();renderRules()}
let collapsedRuleGroups=new Set();
function spokenNumber(text){let words={one:1,two:2,three:3,four:4,five:5,six:6,seven:7,eight:8,nine:9,ten:10,half:.5};let m=text.match(/\d+(?:\.\d+)?/);if(m)return+m[0];for(let w in words)if(new RegExp('\\b'+w+'\\b').test(text))return words[w];return 1}
function durationMinutes(text){let n=spokenNumber(text);if(/hour|hr\b/.test(text))return n*60;if(/minute|min\b/.test(text))return n;return 60}
function analyseRoutineText(raw){let text=raw.toLowerCase(),n=spokenNumber(text),now=new Date().toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'}),base={id:'routine-'+Date.now().toString(36),text:raw,time:now};
 const foods={burger:520,'pizza':285,'roti':110,'chapati':110,'egg':78,'banana':105,'apple':95,'rice':205,'chicken':240,'sandwich':350,'coffee':80,'tea':60,'salad':150,'dal':180,'biryani':550};let food=Object.keys(foods).find(x=>text.includes(x));
 if(food){let kcal=Math.round(foods[food]*n);return{...base,category:'Food',icon:'♨',value:kcal,unit:'kcal',detail:`Estimated ${n} × ${food} · editable`}}
 if(/water|hydration|litre|liter|\bml\b/.test(text)){let amount=n;if(/litre|liter|\bl\b/.test(text))amount*=1000;if(!/ml|litre|liter|\bl\b/.test(text))amount*=250;return{...base,category:'Water',icon:'≈',value:Math.round(amount),unit:'ml',detail:'Added to hydration'}}
 if(/workout|gym|run|running|walk|cycling|exercise|yoga|swim/.test(text)){let min=durationMinutes(text),rate=/run|running/.test(text)?600:/walk/.test(text)?250:/cycling/.test(text)?500:/yoga/.test(text)?220:/swim/.test(text)?550:450,burn=Math.round(min/60*rate);return{...base,category:'Workout',icon:'⌁',value:burn,unit:'kcal burned',detail:`${Math.round(min)} min · estimated`}}
 if(/sleep|slept|nap/.test(text)){let hours=durationMinutes(text)/60;return{...base,category:'Sleep',icon:'☾',value:+hours.toFixed(1),unit:'hours',detail:hours>=7?'Good recovery':'Below sleep target'}}
 if(/work|focus|meeting|proposal|office|client/.test(text)){let hours=durationMinutes(text)/60;return{...base,category:'Work',icon:'→',value:+hours.toFixed(1),unit:'hours',detail:'Focused work logged'}}
 return{...base,category:'Personal',icon:'♡',value:1,unit:'entry',detail:'Personal routine note'}
}
function trackRoutineEntry(text){if(!text.trim())return null;let entry=analyseRoutineText(text.trim());routineLogs.unshift(entry);store.set('tide_routine_logs',routineLogs);renderRoutineTracker();toast(`${entry.category} tracked automatically · ${entry.value} ${entry.unit}`);return entry}
function healthEntryFor(date=localISO()){return healthEntries.find(x=>x.date===date)||null}
function metricTotal(cat){let e=healthEntryFor();if(!e)return 0;let map={Water:'water',Workout:'burn',Sleep:'sleep',Work:'work',Food:'calories'};return +(e[map[cat]]||0)}
function saveHealthEntry(){let date=$('#healthEntryDate').value||localISO(),values={date,calories:+$('#healthCalories').value||0,burn:+$('#healthBurn').value||0,weight:+$('#healthWeight').value||0,work:+$('#healthWork').value||0,water:+$('#healthWater').value||0,sleep:+$('#healthSleep').value||0},existing=healthEntryFor(date);if(existing)Object.assign(existing,values);else healthEntries.push(values);healthEntries.sort((a,b)=>b.date.localeCompare(a.date));store.set('tide_health_entries',healthEntries);renderRoutineTracker();toast('Health numbers saved.')}
function renderRoutineTracker(){let date=$('#healthEntryDate')?.value||localISO(),entry=healthEntryFor(date)||{date,calories:'',burn:'',weight:'',work:'',water:'',sleep:''};$('#healthEntryDate').value=date;[['healthCalories','calories'],['healthBurn','burn'],['healthWeight','weight'],['healthWork','work'],['healthWater','water'],['healthSleep','sleep']].forEach(([id,key])=>$('#'+id).value=entry[key]);renderHealthTable();renderRoutineReport(currentRoutineReport)}
function renderHealthTable(){$('#healthTableBody').innerHTML=healthEntries.length?healthEntries.map((e,i)=>`<tr><td><input type="date" value="${e.date}" data-health-row="${i}" data-health-field="date"></td>${['calories','burn','weight','water','work','sleep'].map(k=>`<td><input type="number" step="0.1" value="${e[k]||0}" data-health-row="${i}" data-health-field="${k}"></td>`).join('')}</tr>`).join(''):'<tr><td colspan="7">No health entries yet.</td></tr>';$$('[data-health-field]').forEach(input=>input.onchange=()=>{let row=healthEntries[+input.dataset.healthRow],key=input.dataset.healthField;row[key]=key==='date'?input.value:+input.value||0;store.set('tide_health_entries',healthEntries);renderRoutineReport(currentRoutineReport)})}
let currentRoutineReport='daily';
function reportHealthEntries(view){let now=new Date(),start=new Date(now);if(view==='daily')return healthEntries.filter(e=>e.date===localISO());if(view==='weekly'){start.setDate(now.getDate()-6);return healthEntries.filter(e=>e.date>=localISO(start)&&e.date<=localISO())}start.setDate(now.getDate()-29);return healthEntries.filter(e=>e.date>=localISO(start)&&e.date<=localISO())}
function renderRoutineReport(view='daily'){currentRoutineReport=view;let list=reportHealthEntries(view),avg=key=>list.length?list.reduce((n,e)=>n+(+e[key]||0),0)/list.length:0,values=[avg('calories')/2200*100,avg('burn')/500*100,avg('weight')/100*100,avg('work')/8*100,avg('water')/3*100,avg('sleep')/8*100],labels=['Calories','Burn','Weight','Work','Water','Sleep'];$('#routineReportEyebrow').textContent=view.toUpperCase()+' REPORT';$('#routineReportTitle').textContent='How your day is balancing.';$('#routineChart').innerHTML=values.map((v,i)=>`<div class="chart-bar-wrap"><div class="chart-bar" style="height:${Math.max(8,Math.min(100,v||0))}%"></div><span>${labels[i]}</span></div>`).join('');let water=avg('water'),sleep=avg('sleep'),insight=$('#routineInsight');$('#routineChart').style.gridColumn=list.length?'':'1/-1';if(!list.length){insight.style.display='none';insight.innerHTML=''}else{insight.style.display='block';let message=`${water<2?'Water is below your target. ':'Hydration is looking steady. '}${sleep<7?'Try protecting more sleep time.':'Your sleep is supporting recovery.'}`;insight.innerHTML=`<span>✦</span><h3>${view==='daily'?'Today’s balance':view==='weekly'?'Seven-day pattern':'Thirty-day pattern'}</h3><p>${message}</p>`;}$$('[data-routine-report]').forEach(b=>b.classList.toggle('active',b.dataset.routineReport===view))}
let calculatorTarget=null,calculatorExpression='';
function openHealthCalculator(inputId){calculatorTarget=inputId;calculatorExpression=$('#'+inputId).value||'';$('#modalBody').innerHTML=`<h2>Calculator</h2><div class="calculator-display" id="calculatorDisplay">${escapeHtml(calculatorExpression||'0')}</div><div class="calculator-grid">${['C','⌫','÷','×','7','8','9','−','4','5','6','+','1','2','3','.','0'].map(x=>`<button data-calc="${x}">${x}</button>`).join('')}<button class="calc-equals" data-calc="=">=</button></div><div class="form-actions"><button class="primary" id="applyCalculation">${inputId?'Use this number':'Copy result'}</button></div>`;$('#modal').classList.add('open');$$('[data-calc]').forEach(b=>b.onclick=()=>calculatorPress(b.dataset.calc));$('#applyCalculation').onclick=()=>{let value=calculateExpression();if(value===null)return toast('Enter a valid calculation.');if(calculatorTarget)$('#'+calculatorTarget).value=value;else navigator.clipboard?.writeText(String(value));$('#modal').classList.remove('open');toast(calculatorTarget?'Number added.':'Result copied.')}}
function calculateExpression(){try{let safe=calculatorExpression.replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-');if(!/^[0-9+*/.()\s-]+$/.test(safe))return null;let value=Function('"use strict";return ('+safe+')')();return Number.isFinite(value)?Math.round(value*100)/100:null}catch{return null}}
function calculatorPress(key){if(key==='C')calculatorExpression='';else if(key==='⌫')calculatorExpression=calculatorExpression.slice(0,-1);else if(key==='='){let result=calculateExpression();if(result!==null)calculatorExpression=String(result)}else calculatorExpression+=key;$('#calculatorDisplay').textContent=calculatorExpression||'0'}
async function downloadHealthPDF(){if(!window.jspdf?.jsPDF){toast('Preparing PDF…');await new Promise((resolve,reject)=>{let script=document.createElement('script');script.src='vendor/jspdf.umd.min.js';script.onload=resolve;script.onerror=reject;document.head.appendChild(script)}).catch(()=>null)}if(!window.jspdf?.jsPDF)return toast('PDF could not load. Check your connection.');let doc=new window.jspdf.jsPDF(),y=20;doc.setFontSize(18);doc.text('Tide Health Data',14,y);y+=12;doc.setFontSize(9);healthEntries.forEach(e=>{let line=`${e.date}  Calories ${e.calories}  Burn ${e.burn}  Weight ${e.weight}kg  Work ${e.work}h  Water ${e.water}L  Sleep ${e.sleep}h`;if(y>280){doc.addPage();y=20}doc.text(line,14,y);y+=8});doc.save('tide-health-data.pdf')}
function meetingDateISO(m){if(m.date)return m.date;return taskDateISO({day:m.day||'Today'})}

