function openTaskTypeSection(id){let routes={meeting:'meetings',reminder:'reminders',followup:'followups',task:'tasks'};if(routes[id])return switchTab(routes[id]);let type=taskTypeById(id),list=tasks.filter(t=>taskCategoryKey(t)===id);$('#modalBody').innerHTML=`<h2>${escapeHtml(type.name)}</h2><p>${list.length} connected items</p><div class="action-list">${list.map(t=>`<button data-custom-task="${t.id}"><strong>${escapeHtml(t.title)}</strong><br><small>${t.time} · ${taskDateISO(t)}</small></button>`).join('')||'<button>No items yet</button>'}</div>`;$('#modal').classList.add('open');$$('[data-custom-task]').forEach(b=>b.onclick=()=>{let i=tasks.findIndex(t=>t.id===b.dataset.customTask);if(i>=0)openTaskActions(i)})}
function prettyDateParts(date){let d=new Date(date+'T00:00:00');return{day:d.toLocaleDateString('en-IN',{day:'2-digit'}),rest:d.toLocaleDateString('en-IN',{month:'short',weekday:'short'})}}
function taskTypeById(id){return taskTypes.find(x=>x.id===id)||taskTypes.find(x=>x.id==='task')||taskTypes[0]}
