function taskCategoryKey(t){if(t.taskTypeId&&taskTypes.some(x=>x.id===t.taskTypeId))return t.taskTypeId;let legacy={'Meeting':'meeting','Reminder':'reminder','Follow-up':'followup','Task':'task'};if(legacy[t.category])return validTaskTypeId(legacy[t.category]);if(meetings.some(m=>m.title.toLowerCase()===t.title.toLowerCase()&&meetingDateISO(m)===taskDateISO(t)))return validTaskTypeId('meeting');if(t.type==='BMC'||t.type==='Personal'||/remind|reminder/i.test(t.title+' '+(t.sub||'')))return validTaskTypeId('reminder');if(t.type==='Work'&&/call|follow|client|payment|proposal|lead/i.test(t.title+' '+(t.sub||'')))return validTaskTypeId('followup');return validTaskTypeId('task')}
