function assistantResponse(query){let q=query.toLowerCase().trim(),today=localISO(),reply,ack=assistantAck(),name=assistantAddress();if(/^(add|create|schedule)|remind me/.test(q)){let category=detectedVoiceCategory(query),date=spokenDateISO(query),time=getTime(query),title=query.replace(/^(please\s+)?(add|create|schedule)\s+(a\s+)?(task|meeting|reminder|follow[- ]?up)?\s*(to\s+)?/i,'').replace(/^remind me (to )?/i,'').trim()||query,selected=taskTypeById(category),type=category==='reminder'?'Personal':'Work',task={id:'task-'+Date.now().toString(36),title,date,day:dateLabel(date),time,createdAt:currentTimeText(),type,taskTypeId:selected.id,category:selected.name,sub:`Assistant · ${selected.name}`,done:false};tasks.unshift(task);if(category==='meeting'){meetings.unshift({title,date,day:task.day,time,sub:'Added by assistant',kind:''});store.set('tide_meetings',meetings)}store.set('tide_tasks',tasks);renderTasks();reply=`${ack}, ${name}. I added ${title} under ${selected.name} for ${dateLabel(date)} at ${time}.`}else if(/complete|mark.*done|finish task/.test(q)){let t=findSpokenTask(q);if(t){t.done=true;t.completedAt=currentTimeText();store.set('tide_tasks',tasks);renderTasks();reply=`${ack}, ${name}. ${t.title} is complete. Nicely done.`}else reply=`I couldn’t identify which task to complete, ${name}. Please say part of its title.`}else if(/move|postpone|tomorrow/.test(q)&&/task|move|postpone/.test(q)){let t=findSpokenTask(q);if(t){let d=new Date();d.setDate(d.getDate()+1);t.date=localISO(d);t.day='Tomorrow';delete t.pendingSince;store.set('tide_tasks',tasks);renderTasks();reply=`${ack}, ${name}. I moved ${t.title} to tomorrow.`}else reply=`I couldn’t identify the task to move, ${name}.`}else if(/read.*(all )?(my )?tasks|list.*tasks/.test(q)){reply=assistantReadList(tasks.filter(t=>!t.done&&taskDateISO(t)===today),'tasks for today')}else if(/read.*meeting|list.*meeting/.test(q)){reply=assistantReadList(tasks.filter(t=>!t.done&&taskCategoryKey(t)==='meeting'),'meetings')}else if(/read.*reminder|list.*reminder/.test(q)){reply=assistantReadList(tasks.filter(t=>!t.done&&taskCategoryKey(t)==='reminder'),'reminders')}else if(/read.*follow|list.*follow/.test(q)){reply=assistantReadList(tasks.filter(t=>!t.done&&taskCategoryKey(t)==='followup'),'follow-ups')}else if(/open (today|home)/.test(q)){switchTab('today');reply=`${ack}, ${name}. Opening Today.`}else if(/open routine/.test(q)){switchTab('routine');reply=`${ack}, ${name}. Opening your routine.`}else if(/open (rules|my rules)/.test(q)){switchTab('rules');reply=`${ack}, ${name}. Opening your rules.`}else if(/open settings/.test(q)){switchTab('settings');reply=`${ack}, ${name}. Opening Settings.`}else if(/start focus|focus mode/.test(q)){openFocusMode();reply=`${ack}, ${name}. Focus Mode is ready. One task at a time.`}else if(/i (drank|ate|slept|worked)|workout|gym/.test(q)){let entry=trackRoutineEntry(query);reply=`${ack}, ${name}. I logged ${entry.value} ${entry.unit} under ${entry.category}.`}else if(/next|priority|what.*do/.test(q)){let t=tasks.find(t=>!t.done&&taskDateISO(t)===today);reply=t?`Your next task is ${t.title}, scheduled for ${t.time}, ${name}.`:`Your list is clear, ${name}. A rare and beautiful sight.`}else if(/follow/.test(q)){let list=tasks.filter(t=>!t.done&&taskCategoryKey(t)==='followup');reply=assistantReadList(list,'pending follow-ups')}else if(/meeting/.test(q)){let list=tasks.filter(t=>!t.done&&taskCategoryKey(t)==='meeting'&&taskDateISO(t)===today);reply=assistantReadList(list,'meetings today')}else if(/routine|health|sleep|water|workout/.test(q)){reply=`Today you logged ${metricTotal('Water')} millilitres of water, ${metricTotal('Workout')} calories of movement, ${metricTotal('Sleep')} hours of sleep, and ${metricTotal('Work')} hours of focused work.`}else if(/brief|today|summary/.test(q)){reply=assistantBriefingText()}else{reply=`I can add, complete, move, and read tasks; manage meetings, reminders, and follow-ups; open sections; start Focus Mode; and summarize your routine. Tell me what you’d like me to do, ${name}.`}assistantMessage(reply);let clipKey='listening';if(/complete|mark.*done|finish task/.test(q))clipKey='taskComplete';else if(/^(add|create|schedule)|remind me/.test(q)){let c=detectedVoiceCategory(query);clipKey=c==='meeting'?'meetingAdded':c==='reminder'?'reminderAdded':c==='followup'?'followupAdded':'listening'}else if(/start focus|focus mode/.test(q))clipKey='focusStarted';else if(/read|brief|summary/.test(q))clipKey='briefingReady';else if(/no pending|list is clear/.test(reply.toLowerCase()))clipKey='listClear';assistantSpeak(reply,false,clipKey);return reply}
